/**
 * Weights used by the v4 feed ranking formula. w_positivity, w_feed_value,
w_quality, and w_category feed into a post's rank_score at LLM
classification time and only affect newly-scored posts.
freshness_halflife_hours, format_multiplier, and sentiment_multiplier
are applied live at feed-read time. like_weight and reply_weight are
applied by the daily job that folds engagement into rank_score.

 */
export interface FeedRankingServiceSettings {
  /** Multiplier applied at feed-read time to posts that have at least
one image asset attached.
 */
  format_multiplier?: number;
  /** The number of hours over which a post's freshness multiplier
decays. Applied live at feed-read time.
 */
  freshness_halflife_hours?: number;
  /** Weight applied per like by the daily engagement job that folds
likes/replies from the last 24 hours into rank_score.
 */
  like_weight?: number;
  /** Weight applied per reply by the daily engagement job that folds
likes/replies from the last 24 hours into rank_score.
 */
  reply_weight?: number;
  /** Multiplier applied at feed-read time to posts with negative
sentiment.
 */
  sentiment_multiplier?: number;
  /** Weight applied to the category boost (only nonzero for positive
sentiment) when computing rank_score.
 */
  w_category?: number;
  /** Weight applied to a post's LLM-derived feed_value_score (0-100)
when computing rank_score.
 */
  w_feed_value?: number;
  /** Weight applied to a post's LLM-derived positivity_score (0-100)
when computing rank_score.
 */
  w_positivity?: number;
  /** Weight applied to the body-length-derived quality_score (25-100)
when computing rank_score.
 */
  w_quality?: number;
}
